import { createVNode, Fragment } from '../create-element';
import { EMPTY_OBJ } from '../constants';
import { isArray } from '../util';

/**
 * Normalize a non-text child into a VNode.
 * @param {import('../internal').VNode | Array<any>} childVNode
 * @returns {import('../internal').VNode}
 */
export function coerceChild(childVNode) {
	if (isArray(childVNode)) {
		return createVNode(
			Fragment,
			{ children: childVNode },
			null,
			null,
			null
		);
	}
	if (childVNode._depth > 0) {
		// VNode is already in use, clone it. This can happen in the following
		// scenario:
		//   const reuse = <div />
		//   <div>{reuse}<span />{reuse}</div>
		return createVNode(
			childVNode.type,
			childVNode.props,
			childVNode.key,
			childVNode.ref ? childVNode.ref : null,
			childVNode._original
		);
	}
	return childVNode;
}

/**
 * Attach a child VNode to its parent and assign depth.
 * @param {import('../internal').VNode} childVNode
 * @param {import('../internal').VNode} parentVNode
 */
export function attachChild(childVNode, parentVNode) {
	childVNode._parent = parentVNode;
	childVNode._depth = parentVNode._depth + 1;
}

/**
 * @param {import('../internal').VNode | object} oldVNode
 * @returns {boolean}
 */
export function isMountingVNode(oldVNode) {
